export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue> {
  const db = getDb();

  db.transaction(() => {
    const current = db
      .select({ projectId: issues.projectId, number: issues.number })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);

    const sourceProjectId = current.projectId as ProjectId;
    rememberIssuedNumber(
      orgId,
      sourceProjectId,
      Math.max(current.number, highestIssuedNumber(orgId, sourceProjectId)),
    );

    db.update(issues)
      .set({
        projectId,
        number: issueNumber,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();

    rememberIssuedNumber(orgId, projectId, issueNumber);
  });

  const moved = await findIssueById(orgId, issueId);
  if (!moved) throw new Error(`Issue ${issueId} not found`);
  return moved;
}

