cat > tests/services/issue-move.test.ts <<'EOF'
/**
 * Moving an issue to another project (ADR 0011).
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { moveIssueToProjectSchema } from "@/schemas/issue";
import { activityFilterSchema } from "@/schemas/activity";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let target: Project;
const detachers: Unsubscribe[] = [];
const published: { type: TaskflowEventType; payload: unknown }[] = [];

const WATCHED: readonly TaskflowEventType[] = [
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "issue.archived",
  "issue.moved",
];

async function newProject(t: Tenant, key: string): Promise<Project> {
  return projectRepo.insertProject({
    orgId: t.org.id,
    name: `${key} project`,
    slug: key.toLowerCase(),
    key,
    description: null,
    visibility: "org",
    leadId: t.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(
    activityService.registerActivityListeners(),
    searchService.registerSearchListeners(),
    ...WATCHED.map((type) =>
      subscribe(type, (payload) => {
        published.push({ type, payload });
      }),
    ),
  );
  tenant = await createTenant("movesvc", "growth");
  other = await createTenant("moveother", "growth");
  target = await newProject(tenant, "OPS");
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

function searchIn(projectId: Project["id"], q: string) {
  return searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds: ["issue"],
    projectId,
    limit: 25,
    cursor: null,
  });
}

describe("moveIssueToProject", () => {
  it("accepts the move payload and the issue.moved audit filter", () => {
    expect(
      moveIssueToProjectSchema.safeParse({
        orgId: tenant.org.id,
        issueId: tenant.project.id,
        toProjectId: target.id,
      }).success,
    ).toBe(true);
    expect(
      activityFilterSchema.safeParse({
        orgId: tenant.org.id,
        action: ["issue.moved"],
      }).success,
    ).toBe(true);
  });

  it("renumbers in the target, retires the old number and announces once", async () => {
    const member = tenant.actors.member;
    await issueService.createIssue(member, issueInput(tenant.org.id, tenant.project.id));
    const issue = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Quebec relocation" }),
    );
    await issueService.createIssue(member, issueInput(tenant.org.id, target.id));
    published.length = 0;

    const moved = await issueService.moveIssueToProject(member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: target.id,
    });

    expect(moved).toMatchObject({
      id: issue.id,
      projectId: target.id,
      number: 2,
      title: issue.title,
      status: issue.status,
      authorId: issue.authorId,
    });
    expect(await issueRepo.findIssueById(tenant.org.id, issue.id)).toEqual(moved);

    expect(published).toHaveLength(1);
    expect(published[0]).toMatchObject({
      type: "issue.moved",
      payload: {
        orgId: tenant.org.id,
        actorId: member.userId,
        issueId: issue.id,
        fromProjectId: tenant.project.id,
        toProjectId: target.id,
        fromNumber: 2,
        toNumber: 2,
      },
    });

    const audit = await activityRepo.listActivityForSubject(tenant.org.id, "issue", issue.id);
    const moves = audit.filter((entry) => entry.action === "issue.moved");
    expect(moves).toHaveLength(1);
    expect(moves[0]).toMatchObject({
      projectId: target.id,
      actorId: member.userId,
      metadata: {
        fromProjectId: tenant.project.id,
        toProjectId: target.id,
        fromNumber: 2,
        toNumber: 2,
      },
    });
    expect(
      audit.find((entry) => entry.action === "issue.created")?.projectId,
    ).toBe(tenant.project.id);

    expect((await searchIn(target.id, "Quebec")).items).toHaveLength(1);
    expect((await searchIn(tenant.project.id, "Quebec")).items).toHaveLength(0);

    // The source project never re-issues the retired number 2.
    const next = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, tenant.project.id),
    );
    expect(next.number).toBe(3);

    // Moving back allocates a fresh number as well.
    const back = await issueService.moveIssueToProject(member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: tenant.project.id,
    });
    expect(back.number).toBe(4);
    expect(await issueRepo.nextIssueNumber(tenant.org.id, target.id)).toBe(3);
  });

  it("does nothing for a move within the same project", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, target.id),
    );
    published.length = 0;

    const same = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: target.id,
    });

    expect(same).toEqual(issue);
    expect(published).toHaveLength(0);
  });

  it("refuses without changing anything", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id),
    );
    published.length = 0;

    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: target.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: other.project.id,
      }),
    ).rejects.toThrow(/not found/);

    expect(await issueRepo.findIssueById(tenant.org.id, issue.id)).toEqual(issue);
    expect(published).toHaveLength(0);
  });
});
EOF
